/* بيانات قسم nsira: تُحمَّل عند أول فتح للقسم */
window.NSIRA = {"c":[{"id":"a","t":"المؤمنات الصالحات: سيَر القنوت والصبر والحياء","d":"نساء مدحهن القرآن بالإيمان والقنوت والصبر والحياء والتوكل، وكل سيرة بمواضعها ودروسها وأقوال المفسرين."},{"id":"b","t":"نساء في موقف الاختبار: عقل وفتنة وتوبة وخيانة","d":"قصص نساء وُضعن أمام اختبار القرار أو الفتنة أو الإيمان، فكان منهن من اهتدى ومن تابت ومن خانت، وفي كلٍّ عبرة."},{"id":"c","t":"نساء بيت النبوة","d":"أمهات المؤمنين وما أنزله الله في شأنهن من الأدب والتبرئة والتخيير."}],"w":[{"id":"maryam","cat":"a","n":"مريم ابنة عمران","intro":"المرأة الوحيدة التي سُمّيت باسمها الصريح في القرآن، وسُمّيت سورة باسمها: نذرتها أمها لله، وكفلها زكريا، واصطفاها الله وطهّرها، واعتزلت للعبادة، فبُشّرت بكلمة منه وحملت بعيسى بلا أب، ثم أتت قومها به فبرّأها وليدها في المهد.","eps":[{"t":"النذر والقبول والكفالة","r":[3,35,37]},{"t":"الاصطفاء والقنوت","r":[3,42,44]},{"t":"البشارة والحمل","r":[19,16,22]},{"t":"المخاض والنخلة والنهر","r":[19,23,26]},{"t":"الإتيان بالولد وكلام المهد","r":[19,27,33]},{"t":"الإحصان وتصديق الكلمات","r":[66,12,12]}],"ls":[{"t":"الاعتزال للعبادة والإخلاص لله","r":[19,16,17],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":16,"x":"{17}{فاتَّخذتۡ من دونهم حجاباً}؛ أي: ستراً ومانعاً، وهذا التباعد منها واتِّخاذ الحجاب لتعتزل وتنفرد بعبادة ربِّها، وتقنت له في حالة الإخلاص والخضوع والذلِّ لله تعالى، وذلك امتثالٌ منها لقوله تعالى:{وإذۡ قالتِ الملائكة يا مريمُ إنَّ الله اصطفاكِ وطهرك واصطفاك على نساءِ العالمينَ.","en":"Al-Sa'di: she placed a screen between herself and her family, this distance being so that she might withdraw and be alone in the worship of her Lord, devout to Him in sincerity, submission and humility."}},{"t":"الرزق كرامة من الله بلا كدّ","r":[3,37,37],"q":{"bk":"saadi","w":"السعدي","s":3,"ay":35,"x":"ثم إن الله تعالى أكرم مريم وزكريا حيث يسَّر لمريم من الرزق الحاصل بلا كدٍّ ولا تعب، وإنما هو كرامة أكرمها الله به، إذ {كلما دخل عليها زكريا المحراب}؛ وهو محل العبادة وفيه إشارة إلى كثرة صلاتها وملازمتها لمحرابها {وجد عندها رزقاً}؛ هنيئاً معدًّا قال:{أنى لك هذا قالت هو من عند الله إن الله يرزقُ من يشاء بغير حساب}؛ فلما رأى زكريا هذه الحال والبر واللطف من الله بها، ذكَّرَه أن يسأل الله تعالى حصول الولد على حين اليأس منه فقال:{رب هَب لي من لَدُنك ذرية طيبة إنك سميعُ الدُّعاء.","en":"Al-Sa'di: Allah honoured Maryam and Zakariyya, easing for Maryam provision that came without effort or fatigue, purely a gift with which Allah honoured her."}},{"t":"تثبيت الله لمن ضاقت عليه الحال","r":[19,24,26],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":23,"x":"{24} فحينئذٍ سكَّن المَلَكُ رَوْعها، وثبَّتَ جأشها، وناداها من تحتها؛ لعلَّه من مكان أنزل من مكانها، وقال لها: لا تَحْزني؛ أي: لا تجزعي ولا تهتمِّي؛ فـ {قد جعل ربُّك تحتك سريًّا}؛ أي: نهراً تشربين منه. {25}{وهُزِّي إليك بجذع النخلةِ تُساقِطۡ عليك رُطَباً جنيًّا}؛ أي: طريًّا لذيذاً نافعاً. {26}{فكُلي}: من التمر، {واشۡربي}: من النهر، {وقَرِّي عَيۡناً}: بعيسى؛ فهذا طمأنينتها من جهة السلامة من ألم الولادة وحصول المأكل والمشرب الهنيِّ، وأما من جهة قالة الناس؛ فأمرها أنَّها إذا رأت أحداً من البشر أنْ تقولَ على وجه الإشارة:{إنِّي نذرتُ للرحمن صوماً}؛ أي: سكوتاً، {فلن أكلِّمَ اليوم إنسيًّا}؛ أي: لا تخاطبيهم بكلام لتستريحي من قولهم وكلامهم، وكان معروفاً عندهم أنَّ السكوت من العبادات المشروعة.","en":"Al-Sa'di: the angel calmed her fear and steadied her heart, calling \"Do not grieve\": a stream beneath her to drink from, ripe dates to shake down, and the command to eat, drink and be content."}},{"t":"الصبر على التهمة وترك الجدال ليكون المهد شاهداً","r":[19,26,29],"q":{"bk":"saadi","w":"السعدي","s":19,"ay":23,"x":"وإنَّما لم تؤمَرْ بمخاطبتهم في نفي ذلك عن نفسها، لأنَّ الناس لا يصدِّقونها، ولا فيه فائدة، وليكون تبرئتها بكلام عيسى في المهد أعظم شاهدٍ على براءتها؛ فإنَّ إتيان المرأة بولدٍ من دون زوج ودعواها أنَّه من غير أحدٍ من أكبر الدعاوى التي لو أقيم عدَّة من الشهود لم تصدَّق بذلك، فجُعِلَتْ بيِّنةُ هذا الخارق للعادة أمراً من جنسه، وهو كلام عيسى في حال صغره جدًّا، ولهذا قال تعالى:","en":"Al-Sa'di: she was told to say only that she had vowed silence, since people would not believe her denial and it would bring no benefit; so that her vindication by Isa in the cradle would be the greatest witness to her innocence."}},{"t":"الصدّيقية: كمال العلم والعمل","r":[66,12,12],"q":{"bk":"saadi","w":"السعدي","s":66,"ay":10,"x":"{12} وقوله: {ومريمَ ابنة عمرانَ التي أحصنتۡ فَرۡجَها}؛ أي: حفظته وصانته عن الفاحشة؛ لكمال ديانتها وعفَّتها ونزاهتها، {فنَفَخۡنا فيه من رُوحنا}: بأن نَفَخَ جبريل عليه السلام في جيب دِرْعها، فوصلت نفخته إلى مريم، فجاء منها عيسى عليه السلام الرسول الكريم والسيد العظيم، {وصَدَّقَتۡ بكلماتِ ربِّها وكتبِهِ}: وهذا وصفٌ لها بالعلم والمعرفة؛ فإنَّ التصديق بكلمات الله يشمل كلماتِهِ الدينيَّة والقدريَّة، والتصديق بكتبه يقتضي معرفة ما به يحصلُ التَّصديق، ولا يكون ذلك إلاَّ بالعلم والعمل، ولهذا قال:{وكانت من القانتينَ}؛ أي: المداومين على طاعة الله بخشيةٍ وخشوعٍ. وهذا وصفٌ لها بكمال العمل؛ فإنَّها رضي الله عنها صدِّيقةٌ. والصدِّيقيَّة هي كمال العلم والعمل.","en":"Al-Sa'di: she guarded and kept her chastity from indecency, out of perfect religion, purity and innocence; and this describes her perfection of deed, for she was a siddiqa, and siddiqiyya is the perfection of knowledge and action."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":19,"ay":23,"x":"* * وَقَوْلُهُ: ﴿فَأَجَاءَهَا الْمَخَاضُ إِلَى جِذْعِ النَّخْلَةِ﴾ [أَيْ: فَاضْطَرَّهَا وَأَلْجَأَهَا الطَّلْقُ إِلَى جِذْعِ النَّخْلَةِ] وَهِيَ نَخْلَةٌ فِي الْمَكَانِ الَّذِي تَنَحَّتْ إِلَيْهِ.","en":"Ibn Kathir on the verse: the labour pains forced and drove her to the trunk of a palm tree, a tree in the place she had withdrawn to."}},{"id":"imran","cat":"a","n":"امرأة عمران (أم مريم)","intro":"نذرت ما في بطنها خادماً لبيت الله، فلما وضعتها أنثى تضرّعت إلى ربها وسمّتها مريم وأعاذتها وذريتها من الشيطان، فتقبّلها الله بقبول حسن؛ وهي من بيت اصطفاه الله على العالمين.","eps":[{"t":"اصطفاء آل عمران","r":[3,33,34]},{"t":"النذر لله","r":[3,35,36]},{"t":"القبول الحسن والإنبات","r":[3,37,37]}],"ls":[{"t":"الإخلاص في النذر وسؤال القبول","r":[3,35,35],"q":{"bk":"saadi","w":"السعدي","s":3,"ay":35,"x":"فلما قرر عظمة هذه البيوت ذكر قصة مريم وابنها عيسى - صلى الله عليه وسلم - وكيف تسلسلا من هذه البيوت الفاضلة، وكيف تنقلت بهما الأحوال من ابتداء أمرهما إلى آخره، وأن امرأة عمران قالت متضرعة إلى ربها متقربة إليه بهذه القربة التي يحبها، التي فيها تعظيم بيته وملازمة طاعته:{إني نذرت لك ما في بطني محرراً}؛ أي خادماً لبيت العبادة المشحون بالمتعبدين {فتقبل مني}؛ هذا العمل أي اجعله مؤسساً على الإيمان والإخلاص مثمراً للخير والثواب {إنك أنت السميع العليم.","en":"Al-Sa'di: she turned to her Lord with a devotion He loves, magnifying His house and keeping to obedience: \"I vow to You what is in my womb, dedicated\", meaning a servant of the house of worship, \"so accept it from me\", that is, found it on faith and sincerity."}},{"t":"جبر الله للقلب المنكسر وتفضيل الأنثى","r":[3,36,37],"q":{"bk":"saadi","w":"السعدي","s":3,"ay":35,"x":"فلما وضعتها قالت رب إني وضعتها أنثى والله أعلم بما وضعت وليس الذكر كالأنثى}؛ كأن في هذا الكلام نوع تضرع منها وانكسار نفس حيث كان نذرها بناءً على أنه يكون ذكراً يحصل منه من القوة والخدمة والقيام بذلك ما يحصل من أهل القوة، والأنثى بخلاف ذلك، فجبر الله قلبها وتقبل الله نذرها، وصارت هذه الأنثى أكمل وأتم من كثير من الذكور، بل من أكثرهم، وحصل بها من المقاصد أعظم مما يحصل بالذكر، ولهذا قال:{فتقبلها ربها بقبول حسن وأنبتها نباتاً حسناً}؛ أي: ربيت تربية عجيبة دينية أخلاقية أدبية، كملت بها أحوالها، وصلحت بها أقوالها وأفعالها، ونما فيها كمالها، ويسر الله لها زكريا كافلاً، وهذا من مِنَّةِ الله على العبد أن يجعل من يتولى تربيته من الكاملين المصلحين.","en":"Al-Sa'di: in her words was supplication and humility, since she had vowed expecting a male; Allah mended her heart and accepted her vow, and this girl became more complete than many males, achieving greater aims; she was raised in a wonderful religious and moral upbringing."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":3,"ay":35,"x":"امْرَأَةُ عِمْرَانَ هَذِهِ أَمُّ مَرْيَمَ [بِنْتِ عِمْرَانَ] عَلَيْهَا السَّلَامُ وَهِيَ حَنَّة بِنْتُ فَاقُوذَ، قَالَ مُحَمَّدُ بْنُ إِسْحَاقَ: وَكَانَتِ امْرَأَةً لَا تَحْمِلُ، فَرَأَتْ يَوْمًا طَائِرًا يَزُقُّ فَرْخَهُ، فَاشْتَهَتِ الْوَلَدَ، فَدَعَتِ اللَّهَ، عَزَّ وَجَلَّ، أَنْ يَهَبَهَا وَلَدًا، فَاسْتَجَابَ اللَّهُ دُعَاءَهَا، فَوَاقَعَهَا زَوْجُهَا، فَحَمَلَتْ مِنْهُ، فَلِمَا تَحَقَّقَتِ الْحَمْلَ نَذَرَتْهُ أَنْ يَكُونَ ﴿مُحَرَّرًا﴾ أَيْ: خَالِصًا مُفَرَّغًا لِلْعِبَادَةِ، وَلِخِدْمَةِ بَيْتِ الْمَقْدِسِ، فَقَالَتْ: ﴿رَبِّ إِنِّي نَذَرْتُ لَكَ مَا فِي بَطْنِي مُحَرَّرًا فَتَقَبَّلْ مِنِّي إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ﴾ أَيْ: السَّمِيعُ لِدُعَائِي، الْعَلِيمُ بِنيتي، وَلَمْ تَكُنْ تَعْلَمُ مَا فِي بَطْنِهَا أَذَكَرًا أَمْ أُنْثَى؟","en":"Ibn Kathir: the wife of Imran is Maryam's mother, Hanna daughter of Faqudh; Ibn Ishaq said she could not conceive, so she asked Allah for a child, and when she knew she was pregnant she vowed it as \"muharrar\", purely devoted to worship and service of Allah's house."}},{"id":"asiya","cat":"a","n":"امرأة فرعون (آسية)","intro":"آمنت في قصر أعتى الطغاة، فضربها الله مثلاً للذين آمنوا: رحمت موسى الرضيع وقالت «قرة عين لي ولك لا تقتلوه»، وسألت ربها بيتاً عنده في الجنة والنجاة من فرعون وعمله.","eps":[{"t":"رحمتها بموسى","r":[28,9,9]},{"t":"دعاؤها: بيت في الجنة","r":[66,11,11]}],"ls":[{"t":"سؤال أجلّ المطالب: الجوار والنجاة","r":[66,11,11],"q":{"bk":"saadi","w":"السعدي","s":66,"ay":10,"x":"{11}{وضرب الله مثلاً للذين آمنوا امرأةَ فرعونَ}: وهي آسيةُ بنتُ مزاحم رضي الله عنها، {إذ قالتۡ ربِّ ابنِ لي عندك بيتاً في الجنَّة ونَجِّني من فرعونَ وعملِهِ ونجِّني من القوم الظَّالمين}: فوصفها الله بالإيمان والتضرُّع لربِّها وسؤالها أجلَّ المطالب، وهو دخول الجنَّة ومجاورة الربِّ الكريم، وسؤالها أن ينجِّيَها [اللَّهُ] من فتنة فرعون وأعماله الخبيثة ومن فتنة كلِّ ظالم، فاستجاب الله لها، فعاشتْ في إيمانٍ كامل وثباتٍ تامٍّ ونجاةٍ من الفتن، ولهذا قال النبيُّ - صلى الله عليه وسلم -: «كَمُلَ من الرجال كثيرٌ، ولم يَكْمُلْ من النساء إلاَّ مريمُ بنتُ عمرانَ، وآسيةُ بنتُ مزاحم، وخديجةُ بنتُ خويلدٍ. وفضلُ عائشةَ على النساء كفضل الثريدِ على سائر الطعام ».","en":"Al-Sa'di: Allah described her with faith and supplication, asking the loftiest things, entering Paradise and neighbourhood of the Generous Lord, and deliverance from Pharaoh's trial and every wrongdoer; He answered her, so she lived in perfect faith and firmness; hence the Prophet said: \"Many men have reached perfection, but of women only Maryam daughter of Imran, Asiya daughter of Muzahim and Khadija daughter of Khuwaylid.\""}},{"t":"الرحمة بالمستضعف في بيت الطغيان","r":[28,9,9],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":7,"x":"{9} فلما التَقَطَهُ آلُ فرعون؛ حنَّن اللهُ عليه امرأة فرعون الفاضلة الجليلة المؤمنة آسية بنت مزاحم، {وقالت}: هذا الولدُ {قُرَّةُ عينٍ لي ولكَ لا تَقۡتُلوهُ}؛ أي: أبقِهِ لنا لِتَقَرَّ به أعينُنا، ونُسَرَّ به في حياتنا، {عسى أن يَنفَعَنا أو نَتَّخِذَه ولداً}؛ أي: لا يخلو: إمَّا أن يكونَ بمنزلة الخدم الذين يَسْعَونَ في نفعنا وخدمتنا، أو نرقِّيه درجةً أعلى من ذلك؛ نجعلُهُ ولداً لنا ونكرِمُه ونُجِلُّه.","en":"Al-Sa'di: when Pharaoh's family picked him up, Allah softened the noble believing wife of Pharaoh, Asiya daughter of Muzahim, who said \"a joy of the eye for me and for you, do not kill him\", that is, keep him so our eyes may be gladdened by him."}},{"t":"المبادرة إلى الإيمان حين يظهر الحق","r":[28,9,9],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":7,"x":"فقدَّر الله تعالى أنَّه نَفَعَ امرأةَ فرعونَ التي قالت تلك المقالة؛ فإنَّه لما صار قُرَّةَ عينٍ لها وأحبَّتْه حبًّا شديداً، فلم يزلْ لها بمنزلة الولد الشفيق، حتى كَبُرَ، ونبَّأه الله، وأرسلَه، فبادرتْ إلى الإسلام والإيمان به، رضي الله عنها، وأرضاها.","en":"Al-Sa'di: Allah decreed that he benefited Pharaoh's wife; she loved him intensely and he stayed like a kindly son until he grew up and Allah made him a prophet and messenger, and she hastened to Islam and faith in him."}}]},{"id":"ummmusa","cat":"a","n":"أم موسى وأخته","intro":"أوحى الله إلى أم موسى أن ترضعه فإذا خافت عليه ألقته في اليمّ، فربط على قلبها حين فرغ، وأمرت أخته أن تقصّ أثره، فردّه الله إليها لتقرّ عينها ولا تحزن ولتعلم أن وعد الله حق.","eps":[{"t":"الوحي والإلقاء في اليمّ","r":[28,7,9]},{"t":"فؤاد فارغ وربط على القلب","r":[28,10,13]},{"t":"المنّة: «ولتصنع على عيني»","r":[20,37,40]}],"ls":[{"t":"الوحي إلى الأم وتقديم البشارة قبل الأمر","r":[28,7,7],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":7,"x":"{7} فأول ذلك لما أوجدَ الله رسولَه موسى الذي جَعَلَ استنقاذَ هذا الشعب الإسرائيليِّ على يديه وبسببه، وكان في وقت تلك المخافة العظيمة التي يذبِّحون بها الأبناء، أوحى إلى أمِّه أن ترضِعَه ويمكثَ عندها، {فإذا خِفۡتِ عليه}: بأن أحسستِ أحداً تخافين عليه منه أن يوصِلَه إليهم، {فألقيه في اليمِّ}؛ أي: نيل مصر، في وسط تابوتٍ مغلق، {ولا تخافي ولا تحزني إنَّا رادُّوه إليك وجاعلوه من المرسلينَ}: فبشَّرها بأنَّه سيردُّه عليها وأنه سيكبر ويَسْلَم من كيدِهم ويجعلُه الله رسولاً، وهذا من أعظم البشائر الجليلة. وتقديم هذه البشارة لأمِّ موسى ليطمئنَّ قلبُها، ويسكنَ رَوْعُها.","en":"Al-Sa'di: in the time of that great fear when sons were being slaughtered, Allah inspired his mother to nurse him and, if she feared, to cast him into the river in a closed chest, and promised to return him and make him a messenger; the glad tidings were put first so that her heart would be at ease and her fear settle."}},{"t":"ربط الله على القلب: الصبر يزيد الإيمان","r":[28,10,10],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":7,"x":"{إن كادَتۡ لَتُبۡدي به}؛ أي: بما في قلبها {لولا أن رَبَطۡنا على قَلۡبها}: فثبَّتْناها، فصبرتْ ولم تُبْدِ به؛ {لتكونَ}: بذلك الصبر والثبات {من المؤمنينَ}: فإنَّ العبد إذا أصابتْه مصيبةٌ فصبر وثبتَ؛ ازداد بذلك إيمانُه، ودلَّ ذلك على أنَّ استمرار الجزع مع العبد دليلٌ على ضعف إيمانه.","en":"Al-Sa'di: \"had We not strengthened her heart\", so she was steadfast and did not disclose it, so that through this patience and firmness she be among the believers; when a servant is struck by a calamity and is patient and firm, his faith increases."}},{"t":"الحزم والحذر في تدبير الأمور","r":[28,11,11],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":7,"x":"{11}{وقالت} أمُّ موسى {لأختِهِ قُصِّيهِ}؛ أي: اذهبي فقُصِّي الأثرَ عن أخيك، وابحثي عنه؛ من غيرِ أن يُحِسَّ بك أحدٌ أو يشعروا بمقصودِك، فذهبتْ تقصُّه، {فبَصُرَتۡ به عن جُنُبٍ وهم لا يَشۡعُرونَ}؛ أي: أبصرتْه على وجهٍ كأنَّها مارةٌ لا قصدَ لها فيه، وهذا من تمام الحزم والحذرِ؛ فإنَّها لو أبصرتْه وجاءتْ إليهم قاصدةً؛ لظنُّوا بها أنها هي التي ألقتْه، فربَّما عزموا على ذبحِهِ عقوبةً لأهله.","en":"Al-Sa'di: she told his sister to follow his trail without anyone feeling her, and she saw him as one passing by with no purpose, which is perfect prudence, for had she come to them intending it, they would have suspected her."}},{"t":"وعد الله حق، ويطمئن به القلب","r":[28,13,13],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":7,"x":"{فَرَدَدۡناه إلى أمِّه}: كما وَعَدْناها بذلك؛ {كي تَقَرَّ عينُها ولا تَحۡزَنَ}: بحيث إنَّه تربَّى عندَها على وجهٍ تكون فيه آمنةً مطمئنةً تفرحُ به وتأخذُ الأجرة الكثيرة على ذلك، {ولِتَعۡلَمَ أنَّ وعدَ الله حقٌّ}: فأريْناها بعضَ ما وَعَدْناها به عياناً ليطمئنَّ بذلك قلبُها ويزدادَ إيمانُها، ولِتَعْلَمَ أنَّه سيحصُلُ وعدُ الله في حفظِهِ ورسالتِهِ.","en":"Al-Sa'di: \"We returned him to his mother as We had promised, that her eye be cooled and she not grieve\", raising him with her in security and gladness while she received a generous wage; \"and that she know that Allah's promise is true\": We showed her some of what We promised so that her heart find rest and her faith grow."}}]},{"id":"madyan","cat":"a","n":"ابنتا صاحب مدين","intro":"امرأتان تذودان غنمهما عن مزاحمة الرجال عند ماء مدين، سقى لهما موسى، فجاءته إحداهما «تمشي على استحياء»، ثم أشارت على أبيها بأن يستأجره لأنه «القوي الأمين».","eps":[{"t":"عند ماء مدين","r":[28,23,24]},{"t":"تمشي على استحياء","r":[28,25,25]},{"t":"«إن خير من استأجرت القوي الأمين»","r":[28,26,28]}],"ls":[{"t":"الخروج للحاجة مع التحفّظ عن مزاحمة الرجال","r":[28,23,23],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":23,"x":"{قالتا لا نسقي حتى يُصۡدِرَ الرِّعاءُ}؛ أي: قد جرتِ العادةُ أنَّه لا يحصُلُ لنا سقي حتى يُصْدِرَ الرعاءُ مواشِيَهم؛ فإذا خلا لنا الجوُّ؛ سقينا، {وأبونا شيخٌ كبيرٌ}؛ أي: لا قوَّة له على السقي، فليس فينا قوَّةٌ نقتدِرُ بها، ولا لنا رجالٌ يزاحِمون الرعاء.","en":"Al-Sa'di: the two women said, \"we do not water until the shepherds withdraw\", for the custom was that they could not water until the place was empty; \"and our father is a very old man\", with no strength to water, nor have we men to compete with the shepherds."}},{"t":"الحياء من الأخلاق الفاضلة","r":[28,25,25],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":23,"x":"{25} فلم يزل في هذه الحالة داعياً ربه متملِّقاً، وأما المرأتان؛ فذهبتا إلى أبيهما وأخبرتاه بما جرى، فأرسل أبوهما إحداهما إلى موسى، فجاءته {تمشي على استحياءٍ}، وهذا يدلُّ على كرم عنصرِها وخُلُقها الحسن؛ فإنَّ الحياء من الأخلاق الفاضلة، وخصوصاً في النساء، ويدلُّ على أنَّ موسى عليه السلام لم يكنْ فيما فعله من السقي لهما بمنزلة الأجير والخادم الذي لا يستحى منه عادة، وإنَّما هو عزيزُ النفس، رأتْ من حسنِ خُلُقِهِ ومكارم أخلاقه ما أوجبَ لها الحياء منه، {قالتۡ}: له: {إنَّ أبي يدعوكَ لِيَجۡزِيَكَ أجرَ ما سَقَيۡتَ لنا}؛ أي: لا لمنٍّ عليك، بل أنت الذي ابتدأتنا بالإحسان، وإنَّما قصدُه أن يكافِئَك على إحسانِك، فأجابها موسى، {فلمَّا جاءه وقصَّ عليه القَصَصَ}: من ابتداء السبب الموجب لهربِهِ إلى أن وَصَلَ إليه، {قال}: له مسكِّناً رَوْعَهُ جابراً قَلْبَهُ: {لا تَخَفۡ نجوتَ من القوم الظالمينَ}؛ أي: ليذهبْ خوفُك ورَوْعُك؛ فإنَّ الله نجَّاك منهم حيث وصلتَ إلى هذا المحلِّ الذي ليس لهم عليه سلطانٌ.","en":"Al-Sa'di: her coming \"walking shyly\" shows the nobility of her nature and her good character, for modesty is among the virtuous traits, especially in women; it also shows that Musa was no hired servant, but a self-respecting man whose noble conduct made her shy before him."}},{"t":"القوة والأمانة: ميزان من تستعمله في عمل","r":[28,26,26],"q":{"bk":"saadi","w":"السعدي","s":28,"ay":23,"x":"{26}{قالتۡ إحداهُما}؛ أي: إحدى ابنتيهِ: {يا أبتِ اسۡتَأجِرۡه}؛ أي: اجْعَلْه أجيراً عندك يرعى الغنم ويسقيها، {إنَّ خير مَنِ استأجرتَ القويُّ الأمينُ}؛ أي: إنَّ موسى أولى مَنِ استُؤْجِرَ؛ فإنَّه جمع القوَّة والأمانة، وخير أجيرٍ استُؤْجِرَ مَن جَمَعَهما؛ [أي]: القوَّة والقدرة على ما استُؤْجِرَ عليه، والأمانة فيه بعدم الخيانة، وهذان الوصفان ينبغي اعتبارُهما في كلِّ مَنْ يَتَوَلَّى للإنسان عملاً بإجارة أو غيرها؛ فإنَّ الخلل لا يكون إلا بفقدِهِما أو فقد إحداهما، وأمَّا اجتماعُهما؛ فإنَّ العمل يتمُّ ويكمُلُ.","en":"Al-Sa'di: the best employee is one who combines strength and ability for the task with trustworthiness and no betrayal; these two traits are to be considered in anyone who takes charge of work for a person, since defect comes only from lacking them, and when both are present the work is complete."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":28,"ay":23,"x":"﴿وَلَمَّا وَرَدَ مَاءَ مَدْيَنَ﴾ أَيْ: وَلَمَّا وَصَلَ إِلَى مَدْيَنَ وَوَرَدَ مَاءَهَا، وَكَانَ لَهَا بِئْرٌ تَرده رِعَاءُ الشَّاءِ ﴿وَجَدَ عَلَيْهِ أُمَّةً مِنَ النَّاسِ﴾ أَيْ: جَمَاعَةً ﴿يَسْقُونَ وَوَجَدَ مِنْ دُونِهِمُ امْرَأتَيْنِ تَذُودَانِ﴾ أَيْ: تُكَفْكِفَانِ غَنَمَهُمَا أَنْ تَرِدَ مَعَ غَنَمِ أُولَئِكَ الرِّعَاءِ لِئَلَّا يُؤذَيا.","en":"Ibn Kathir: when Musa reached Madyan and came to its water, where shepherds watered their sheep, he found a group of people watering and two women beside them holding back their flock so that it not mix with the shepherds' flocks and cause them harm."}},{"id":"sarah","cat":"a","n":"امرأة إبراهيم (سارة)","intro":"كانت قائمة تخدم أضياف زوجها الملائكة، فضحكت، فبُشّرت بإسحاق ومن وراء إسحاق يعقوب على كبر وعقم، فقالت «يا ويلتى أألد وأنا عجوز»، فقيل لها: «أتعجبين من أمر الله؟».","eps":[{"t":"الملائكة عند إبراهيم","r":[11,69,70]},{"t":"الضحك والبشرى","r":[11,71,73]},{"t":"الذاريات: صكّت وجهها","r":[51,24,30]}],"ls":[{"t":"خدمة الضيف من أخلاق البيت المبارك","r":[11,69,71],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":69,"x":"{71} وامرأة إبراهيم {قائمةٌ}: تخدُمُ أضيافَه، {فضَحِكَتۡ}: حين سمعتْ بحالهم وما أرسلوا به تعجُّباً، {فبشَّرۡناها بإسحاقَ ومن وراءِ إسحاق يعقوبَ}.","en":"Al-Sa'di: the wife of Ibrahim was standing, serving his guests; she laughed when she heard of their state and what they were sent with, in wonder; then We gave her glad tidings of Ishaq and, after Ishaq, Yaqub."}},{"t":"لا عجب في أمر الله","r":[11,73,73],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":69,"x":"{73}{قالوا أتَعۡجَبين من أمرِ الله}: فإنَّ أمره لا عجب فيه؛ لنفوذ مشيئته التامَّة في كل شيءٍ؛ فلا يُستغرب على قدرته شيء، وخصوصاً فيما يدبِّره ويمضيه لأهل هذا البيت المبارك.","en":"Al-Sa'di: \"Do you wonder at the decree of Allah?\", for there is nothing strange in His decree by the full execution of His will in everything; nothing is strange to His power, especially what He manages and carries out for the people of this blessed house."}},{"t":"رحمة الله وبركاته على أهل البيت","r":[11,73,73],"q":{"bk":"saadi","w":"السعدي","s":11,"ay":69,"x":"{رحمةُ الله وبركاتُهُ} عليكم أهل البيت؛ أي: لا تزال رحمته وإحسانه وبركاته، وهي الزيادة من خيره وإحسانه وحلول الخير الإلهي على العبد. {عليكم أهلَ البيت إنَّه حميدٌ مجيدٌ}؛ أي: حميد الصفات؛ لأنَّ صفاته صفات كمال، حميدُ الأفعال؛ لأنَّ أفعاله إحسانٌ وجودٌ وبرٌّ وحكمةٌ وعدلٌ وقِسْطٌ.","en":"Al-Sa'di: \"the mercy of Allah and His blessings upon you, people of the house\", that is, His mercy, kindness and blessings never cease, as increase of His good and descent of divine good upon the servant; He is Praiseworthy in His attributes, for His attributes are perfection, and praiseworthy in His acts, which are kindness, generosity, righteousness, wisdom and justice."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":11,"ay":71,"x":"فَضَحِكَتْ سَارَّةُ اسْتِبْشَارًا [مِنْهَا] بِهَلَاكِهِمْ، لِكَثْرَةِ فَسَادِهِمْ، وغِلَظ كفرهم وعنادهم، فلهذا جوزيت بالبشارة بِالْوَلَدِ بَعْدَ الْإِيَاسِ. وَقَالَ قَتَادَةُ: ضَحِكَتْ [امْرَأَتُهُ] وَعَجِبَتْ [مِنْ] أَنَّ قَوْمًا يَأْتِيهِمُ الْعَذَابُ وَهُمْ فِي غَفْلَةٍ [فَضَحِكَتْ مِنْ ذَلِكَ وَعَجِبَتْ فَبَشَّرْنَاهَا بِإِسْحَاقَ] .","en":"Ibn Kathir: Sarah laughed in gladness at their destruction for their abundant corruption and stubborn disbelief, so she was rewarded with the glad tidings of a child after despair; Qatada said she laughed and wondered that a people were about to be seized while heedless."}},{"id":"khawla","cat":"a","n":"المجادِلة التي سمع الله قولها","intro":"اشتكت إلى الله وإلى رسوله أمر زوجها حين ظاهر منها، فأنزل الله «قد سمع الله قول التي تجادلك في زوجها»، وشرع به حكم الظهار وكفارته. ولم يُسمّها القرآن، وسمّاها المفسرون: خولة بنت ثعلبة.","eps":[{"t":"شكواها وسمع الله","r":[58,1,1]},{"t":"حكم الظهار","r":[58,2,4]}],"ls":[{"t":"الله يسمع شكوى المستضعف","r":[58,1,1],"q":{"bk":"saadi","w":"السعدي","s":58,"ay":1,"x":"{إنَّ الله سميعٌ}: لجميع الأصوات في جميع الأوقات على تفنُّن الحاجات. {بصيرٌ}: يبصر دبيبَ النملة السوداء، على الصَّخرة الصمَّاء، في الليلة الظلماء. وهذا إخبارٌ عن كمال سمعه وبصره، وإحاطتهما بالأمور الدَّقيقة والجليلة، وفي ضمن ذلك الإشارة بأنَّ الله [تعالى] سيزيلُ شكواها ويرفع بلواها، ولهذا ذكر حكمها وحكمَ غيرها على وجه العموم، فقال: {2}{الذين يظاهِرونَ منكم من نسائِهِم ما هنَّ أمَّهاتِهم إن أمَّهاتُهم إلاَّ اللاَّئي وَلَدۡنَهم}: المظاهرة من الزوجة أن يقولَ الرجل لزوجته: أنت عليَّ كظهرِ أمِّي، أو غيرها من محارمه، أو أنت عليَّ حرامٌ.","en":"Al-Sa'di: \"Allah is Hearing\", of all voices at all times, \"Seeing\", He sees the step of the black ant on a smooth rock in a dark night; this reports the perfection of His hearing and sight, and in it a hint that Allah will remove her complaint and lift her affliction."}},{"t":"قبح الظهار وبيان منكره","r":[58,2,2],"q":{"bk":"saadi","w":"السعدي","s":58,"ay":1,"x":"وكان المعتاد عندَهم في هذا اللفظ الظهر، ولهذا سماه الله ظِهاراً، فقال:{الذين يظاهِرون منكم من نسائِهِم ما هنَّ أمَّهاتِهم}؛ أي: كيف يتكلَّمون بهذا الكلام الذي يعلمون أنَّه لا حقيقة له، فيشبهون أزواجهم بأمَّهاتِهم اللاَّتي ولدنهم؟! ولهذا عظَّم الله أمره وقبَّحه، فقال:{وإنَّهم لَيقولونَ منكراً من القول وزوراً}؛ أي: قولاً شنيعاً وكذباً ، {وإنَّ الله لَعَفُوٌّ غفورٌ}: عمَّن صَدَرَ منه بعضُ المخالفات فتداركَها بالتَّوْبَةِ النَّصوح.","en":"Al-Sa'di: how can they speak words they know have no reality, likening their wives to their mothers who bore them? Hence Allah magnified its matter and made it ugly: \"and they say a wrong word and a falsehood\", while \"Allah is Pardoning, Forgiving\" to whoever repents sincerely."}}],"ctx":{"bk":"qurtubi","w":"القرطبي","s":58,"ay":1,"x":"هي خولة بِنْتُ ثَعْلَبَةَ سَمِعَ اللَّهُ قَوْلَهَا مِنْ فَوْقِ سَبْعِ سَمَوَاتٍ، أَيَسْمَعُ رَبُّ الْعَالَمِينَ قَوْلَهَا وَلَا يَسْمَعُهُ عُمَرُ؟ وَقَالَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا: تبارك الذي وسع سمعه كل شي، إِنِّي لَأَسْمَعَ كَلَامَ خَوْلَةَ بِنْتِ ثَعْلَبَةَ وَيَخْفَى عَلَيَّ بَعْضُهُ، وَهِيَ تَشْتَكِي زَوْجَهَا إِلَى رَسُولِ اللَّهِ ﷺ، وَهِيَ تَقُولُ: يَا رَسُولَ اللَّهِ!","en":"Al-Qurtubi: she is Khawla bint Tha'laba, whose speech Allah heard from above the seven heavens; \"would the Lord of the worlds hear her speech and Umar not hear it?\" And Aisha said: blessed is He whose hearing encompasses everything; I heard the words of Khawla bint Tha'laba while some of it was hidden from me, as she was complaining of her husband to the Messenger of Allah ﷺ, saying: O Messenger of Allah!"}},{"id":"bilqis","cat":"b","n":"ملكة سبأ","intro":"امرأة تملك قومها وأوتيت من كل شيء ولها عرش عظيم، كانت تسجد هي وقومها للشمس، فجاءها كتاب سليمان، فشاورت ملأها ولم تستبد، وجرّبت بهدية، ثم أسلمت لله رب العالمين. ولم يُسمّها القرآن؛ ويُنقل عن المفسرين تسميتها بلقيس.","eps":[{"t":"نبأ الهدهد","r":[27,22,26]},{"t":"الكتاب والمشاورة","r":[27,27,35]},{"t":"الهدية والعرش","r":[27,36,42]},{"t":"الصرح والإسلام","r":[27,43,44]}],"ls":[{"t":"المشورة وعدم الاستبداد بالأمر","r":[27,32,33],"q":{"bk":"saadi","w":"السعدي","s":27,"ay":22,"x":"{32 ـ 33} فمن حزمها وعقلها أنْ جمعت كبارَ دولتها ورجال مملكَتِها وقالت: {يا أيُّها الملأ أفتوني في أمري}؛ أي: أخبروني ماذا نجيبُه به؟! وهل ندخُلُ تحت طاعتِهِ وننقادُ أم ماذا نفعل؟! {ما كنتُ قاطعةً أمراً حتى تَشۡهَدونِ}؛ أي: ما كنتُ مستبدَّةً بأمرٍ دون رأيكم ومشورَتِكم، {قالوا نحنُ أولو قوَّةٍ وأولو بأس شديدٍ}؛ أي: إن رددتِ عليه قولَه، ولم تدخُلي في طاعتِهِ؛ فإنَّا أقوياء على القتال.","en":"Al-Sa'di: from her prudence and wisdom she gathered the elders of her state and said, \"Advise me in my matter\"; how shall we answer him, shall we submit and obey? \"I was not deciding a matter until you were present\", meaning I never act alone without your opinion and counsel."}},{"t":"النظر في عاقبة الحرب لا قوتها","r":[27,34,35],"q":{"bk":"saadi","w":"السعدي","s":27,"ay":22,"x":"{34 ـ 35} فقالت لهم مقنعةً لهم عن رأيِهِم، ومبيِّنة سوء مغبَّة القتال:{إنَّ الملوكَ إذا دخلوا قريةً أفسَدوها}: قتلاً وأسراً ونهباً لأموالها وتخريباً لديارها، {وجعلوا أعِزَّةَ أهلها أذِلَّةً}؛ أي: جعلوا الرؤساء السادة أشراف الناس من الأرذلين ؛ أي: فهذا رأيٌ غير سديد، وأيضاً؛ فلست بمطيعةٍ له قبل الاختبار وإرسال مَنْ يكشِفُ عن أحواله ويتدبَّرُها، وحينئذٍ نكونُ على بصيرةٍ من أمرِنا.","en":"Al-Sa'di: she convinced them to turn from their view and showed the evil end of fighting: \"kings, when they enter a town, ruin it\", through killing, captivity, plunder and wrecking of homes, \"and make the noblest of its people the lowest\"."}},{"t":"اختبار الأمر قبل الحكم: الهدية","r":[27,35,35],"q":{"bk":"saadi","w":"السعدي","s":27,"ay":22,"x":"فقالت:{وإنِّي مرسلةٌ إليهم بهديَّةٍ فناظرةٌ بم يَرۡجِعُ المرسلونَ}: منه؛ هل يستمرُّ على رأيِهِ وقولِهِ؟ أم تخدعُهُ الهديةُ وتُبَدِّلُ فكرتَه؟! وكيف أحوالُه وجنودُه؟!","en":"Al-Sa'di: \"I am sending them a gift, and will see with what the envoys return\": does he persist in his view and word? Or does the gift deceive him and change his thinking? And how are his state and troops?"}},{"t":"الفطنة: «كأنه هو»","r":[27,42,42],"q":{"bk":"saadi","w":"السعدي","s":27,"ay":22,"x":"{قالتۡ كأنَّه هو}: وهذا من ذكائِها وفطنتِها: لم تَقُلْ هو لوجود التغيير فيه والتنكير، ولم تَنْفِ أنَّه هو لأنها عَرَفَتْه، فأتت بلفظٍ محتمل للأمرين، صادقٍ على الحالين.","en":"Al-Sa'di: this shows her intelligence and shrewdness: she did not say it is it, given the alteration, nor deny that it was it, because she recognised it; so she used a phrase that fits both cases and is true in both."}},{"t":"العقيدة الباطلة تحجب بصيرة القلب","r":[27,43,43],"q":{"bk":"saadi","w":"السعدي","s":27,"ay":22,"x":"{43} قال الله تعالى: {وصدَّها ما كانتۡ تعبُدُ من دونِ الله}؛ أي: عن الإسلام، وإلاَّ؛ فلها من الذكاء والفطنة ما به تعرفُ الحقَّ من الباطل، ولكنَّ العقائدَ الباطلة تُذْهِبُ بصيرة القلب.","en":"Al-Sa'di: \"what she used to worship besides Allah kept her back\", from Islam; otherwise she had the intelligence and shrewdness by which she knew truth from falsehood, but false beliefs take away the heart's insight."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":27,"ay":44,"x":"وَقَالَ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ يَزِيدَ بْنِ رُومان: ثُمَّ قَالَ لَهَا: ادْخُلِي الصَّرْحَ، لِيُرِيَهَا مُلْكًا هُوَ أَعَزُّ مِنْ مُلْكِهَا، وَسُلْطَانًا هُوَ أَعْظَمُ مِنْ سُلْطَانِهَا.","en":"Ibn Kathir, from Ibn Ishaq on the authority of Yazid ibn Ruman: then he said to her \"Enter the palace\", to show her a kingdom greater than hers and a sovereignty mightier than her sovereignty."}},{"id":"aziz","cat":"b","n":"امرأة العزيز","intro":"راودت فتاها يوسف عن نفسه وغلّقت الأبواب، فامتنع وفرّ، وشهد شاهد من أهلها، وأُمرت بالاستغفار، ثم لما ظهر الحق قالت «الآن حصحص الحق أنا راودته عن نفسه وإنه لمن الصادقين». ولم يُسمّها القرآن، وإنما سمّاها «امرأة العزيز». واختلف المفسرون في نسبة «ذلك ليعلم أني لم أخنه بالغيب» وما بعده إلى يوسف أو إليها؛ ومذهب السعدي أنه قولها، ومال ابن كثير إلى أنه قول يوسف.","eps":[{"t":"المراودة وتغليق الأبواب","r":[12,23,25]},{"t":"الشاهد والأمر بالاستغفار","r":[12,26,29]},{"t":"مكر النسوة","r":[12,30,34]},{"t":"الاعتراف: حصحص الحق","r":[12,50,53]}],"ls":[{"t":"الأمر بالإعراض والاستغفار والتوبة","r":[12,29,29],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":23,"x":"{29} ثم إنَّ سيدَها لما تحقَّق الأمر؛ قال ليوسف:{يوسُفُ أعرِضۡ عن هذا}؛ أي: اترك الكلام فيه وتناسَهُ ولا تذكُره لأحدٍ طلباً للستر على أهله. {واستغفِري}: أيتها المرأة، {لذنبِكِ إنَّك كنتِ من الخاطئين}: فأمر يوسف بالإعراض، وهي بالاستغفارِ والتوبة.","en":"Al-Sa'di: her master told Yusuf to turn from this and forget it, not mentioning it to anyone, in order to cover for his family; and to her, \"seek forgiveness for your sin, you were of the sinners\"; so Yusuf was ordered to turn away and she to seek forgiveness and repent."}},{"t":"الاعتراف بالحق وإن كان على النفس","r":[12,51,51],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":51,"x":"فبرَّأنَه و {قلن حاشَ لله ما علِمۡنا عليه من سوءٍ}؛ أي: لا قليل ولا كثير؛ فحينئذ زال السببُ الذي تُبْنَى عليه التُّهمة، ولم يبقَ إلاَّ ما عند امرأة العزيز، فقالتِ {امرأة العزيز الآنَ حَصۡحَصَ الحقُّ}؛ أي: تمحَّص وتبيَّن بعدما كنَّا نُدْخِل معه من السوء والتُّهمة ما أوجب السجن ليوسف ، {أنا راودتُه عن نفسِهِ وإنَّه لمن الصادقينَ}: في أقواله وبراءته.","en":"Al-Sa'di: the women cleared him and said \"Allah forbid, we know of no evil in him\", so the cause of the accusation vanished and only what remained with the wife of al-Aziz; she said, \"Now the truth has become clear\"."}},{"t":"الخيانة تعود على صاحبها ويتبيّن أمرها","r":[12,52,52],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":51,"x":"{وأنَّ الله لا يَهۡدي كيد الخائنين}: فإنَّ كلَّ خائنٍ لا بدَّ أن تعود خيانته ومكره على نفسه، ولا بدَّ أن يتبيَّن أمره.","en":"Al-Sa'di: \"and that Allah does not guide the plot of the betrayers\": every betrayer's betrayal and scheming must return upon himself, and his affair must become plain."}},{"t":"النفس أمّارة بالسوء إلا ما رحم ربي","r":[12,53,53],"q":{"bk":"saadi","w":"السعدي","s":12,"ay":51,"x":"{53} ثم لما كان في هذا الكلام نوعُ تزكيةٍ لنفسها وأنه لم يجر منها ذنبٌ في شأن يوسف استدركت فقالت: {وما أُبَرِّئُ نَفۡسِي}؛ أي: من المراودة والهمِّ والحرص الشديد والكيد في ذلك. {إنَّ النفس لأمارةٌ بالسوءِ}؛ أي: لكثيرة الأمر لصاحبها بالسوء؛ أي: الفاحشة وسائر الذنوب؛ فإنَّها مركَبُ الشيطان، ومنها يدخُلُ على الإنسان. {إلاَّ ما رَحِمَ ربي}: فنجَّاه من نفسه الأمَّارة حتى صارت نفسُهُ مطمئنةً إلى ربِّها منقادة لداعي الهدى متعاصية عن داعي الرَّدى؛ فذلك ليس من النفس، بل من فضل الله ورحمته بعبده.","en":"Al-Sa'di, on this saying as hers: \"I do not absolve myself\", of solicitation, intent, intense desire and plotting; \"the soul commands evil\", it is the mount of Satan through which he enters man; \"except what my Lord has mercy upon\", sparing him from his commanding soul until it becomes at peace with its Lord; that is not from the soul but from Allah's grace and mercy."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":12,"ay":51,"x":"فَعِنْدَ ذَلِكَ ﴿قَالَتِ امْرَأَةُ الْعَزِيزِ الآنَ حَصْحَصَ الْحَقُّ﴾ قَالَ ابْنُ عَبَّاسٍ، وَمُجَاهِدٌ، وَغَيْرُ وَاحِدٍ: تَقُولُ الْآنَ: تَبَيَّنَ الْحَقُّ وَظَهَرَ وَبَرَزَ.","en":"Ibn Kathir: at that point \"the wife of al-Aziz said, Now the truth has become clear\"; Ibn Abbas, Mujahid and others said: she means now the truth has appeared, emerged and become plain."}},{"id":"hawwa","cat":"b","n":"زوج آدم (حواء)","intro":"أسكنها الله الجنة مع آدم، فاغترّا بوسوسة إبليس، ثم اعترفا معاً بالذنب وسألا المغفرة: «ربنا ظلمنا أنفسنا». فالقرآن يشركهما في الخطاب والتوبة معاً. ولم يُسمّها القرآن؛ وتسميتها حواء من أقوال المفسرين.","eps":[{"t":"سكنى الجنة","r":[2,35,35]},{"t":"وسوسة إبليس والأكل","r":[7,19,22]},{"t":"التوبة المشتركة","r":[7,23,25]}],"ls":[{"t":"السكن إلى الزوج نعمة من الله","r":[7,19,19],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":19,"x":"{19} أي: أمر الله تعالى آدم وزوجته حواء التي أنعم الله بها عليه ليسكن إليها أن يأكلا من الجنة حيث شاءا ويتمتعا فيها بما أرادا؛ إلا أنه عيَّن لهما شجرةً ونهاهما عن أكلها، والله أعلم ما هي، وليس في تعيينها فائدةٌ لنا، وحرَّم عليهما أكلها؛ بدليل قوله:{فتكونا من الظالمين}.","en":"Al-Sa'di: Allah commanded Adam and his wife Hawwa, whom He favoured him with to find rest in her, to eat from the Garden wherever they wished, but He specified a tree and forbade them to eat of it."}},{"t":"غلبة الشهوة على العقل لحظة الاغترار","r":[7,20,22],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":19,"x":"{22} فاغترَّا بذلك، وغلبت الشهوة في تلك الحال على العقل، {فدلاَّهما}؛ أي: أنزلهما عن رتبتهما العالية التي هي البعدُ عن الذنوب والمعاصي إلى التلوُّث بأوضارِها، فأقدما على أكلها، {فلمَّا ذاقا الشجرةَ بَدَتۡ لهما سوآتُهما}؛ أي: ظهرت عورة كل منهما بعدما كانت مستورةً، فصار للعري الباطن من التقوى في هذه الحال أثرٌ في اللباس الظاهر حتى انخلع، فظهرت عوراتُهما، ولما ظهرتْ عوراتُهما؛ خَجِلا وجَعَلا يخصِفان على عوراتهما من أوراق شجر الجنة ليستترا بذلك، {وناداهما ربهما}: وهما بتلك الحال ـ موبِّخاً ومعاتباً ـ: {ألم أنۡهَكُما عن تلكما الشجرةِ وأقل لكما إنَّ الشيطان لكما عدوٌّ مبينٌ}: فَلِمَ اقترفتُما المنهيَّ وأطعتما عدوَّكما؟!","en":"Al-Sa'di: they were deceived by that, desire overcame reason at that moment, so He brought them down from their high rank, far from sins and disobedience, to the stain of their impurities, and they ate; when they tasted the tree their private parts appeared."}},{"t":"الاعتراف والاستغفار طريق الاجتباء","r":[7,23,23],"q":{"bk":"saadi","w":"السعدي","s":7,"ay":19,"x":"{23} فحينئذٍ مَنَّ الله عليهما بالتوبة وقَبولها، فاعترفا بالذنب، وسألا من الله مغفرتَه، فقالا:{ربَّنا ظَلمۡنا أنفُسَنا وإن لم تغفرۡ لنا وترحَمۡنا لَنَكونَنَّ من الخاسرينَ}؛ أي: قد فعلنا الذنب الذي نبَّهتنا عنه وأضررنا بأنفسنا باقتراف الذنب، وقد فعلنا سببَ الخسار إن لم تغفرْ لنا بمحو أثر الذنب وعقوبته وترحَمْنا بقَبول التوبة والمعافاة من أمثال هذه الخطايا، فغفر الله لهما ذلك، وعصى آدمُ ربَّه فغوى.","en":"Al-Sa'di: then Allah favoured them with repentance and its acceptance; they confessed the sin and asked His forgiveness, saying \"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy on us, we will be among the losers\"."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":7,"ay":19,"x":"يَذْكُرُ تَعَالَى أَنَّهُ أَبَاحَ لِآدَمَ، عَلَيْهِ السَّلَامُ، وَلِزَوْجَتِهِ [حَوَّاءَ] الْجَنَّةَ أَنْ يَأْكُلَا مِنْهَا مِنْ جَمِيعِ ثِمَارِهَا إِلَّا شَجَرَةً وَاحِدَةً.","en":"Ibn Kathir: Allah informs that He permitted Adam and his wife Hawwa the Garden, to eat from all its fruits except one tree."}},{"id":"nuhlut","cat":"b","n":"امرأة نوح وامرأة لوط","intro":"ضرب الله بهما المثل للذين كفروا: كانتا تحت عبدين صالحين فخانتاهما في الدين، فلم يغنيا عنهما من الله شيئاً. ولم يُسمّهما القرآن، وفي أسمائهما اختلاف بين المفسرين.","eps":[{"t":"مثل للذين كفروا","r":[66,10,10]},{"t":"امرأة لوط في الهالكين","r":[11,81,81]},{"t":"الغابرة","r":[7,83,83]}],"ls":[{"t":"الخيانة في الدين لا في العرض","r":[66,10,10],"q":{"bk":"saadi","w":"السعدي","s":66,"ay":10,"x":"{10}{ضَرَبَ الله مثلا للذين كَفَروا امرأة نوحٍ وامرأة لوطٍ كانتا}؛ أي: المرأتان {تحت عبدينِ من عبادِنا صالِحَيۡنِ}: وهما نوحٌ ولوطٌ عليهما السلام، {فخانَتاهما}: في الدين؛ بأن كانتا على غير دين زوجيهما، وهذا المراد بالخيانة، لا خيانة النَّسب والفراش؛ فإنَّه ما بغت امرأةُ نبيِّ قطُّ، وما كان الله ليجعلَ امرأةَ أحدٍ من أنبيائه بَغِيًّا، {فلم يُغۡنيا}؛ أي: نوحٌ ولوطٌ {عنهما}؛ أي: عن امرأتيها، {من اللهِ شيئاً وقيل} لهما {ادۡخُلا النارَ مع الدَّاخِلين}.","en":"Al-Sa'di: \"they betrayed them\", in religion, by being of other than their husbands' religion; this is the meaning of betrayal, not betrayal of lineage and bed, since no prophet's wife ever committed adultery, and Allah never made the wife of any of His prophets one who does; \"so they availed them nothing against Allah\", and it was said to them \"enter the Fire with those who enter\"."}},{"t":"لا يغني القريب عن قريبه إذا فرّق بينهما الدين","r":[66,10,10],"q":{"bk":"qurtubi","w":"القرطبي","s":66,"ay":10,"x":"ضَرَبَ اللَّهُ تَعَالَى هَذَا الْمَثَلَ تَنْبِيهًا عَلَى أَنَّهُ لَا يُغْنِي أَحَدٌ فِي الْآخِرَةِ عَنْ قَرِيبٍ وَلَا نَسِيبٍ إِذَا فَرَّقَ بَيْنَهُمَا الدِّينُ.","en":"Al-Qurtubi: Allah gave this example as a warning that no one will avail another in the Hereafter, relative or kin, when religion separates them."}}],"ctx":{"bk":"qurtubi","w":"القرطبي","s":66,"ay":10,"x":"وَقَالَ سُلَيْمَانُ بْنُ رُقَيَّةَ عَنِ ابْنِ عَبَّاسٍ: كَانَتِ امْرَأَةُ نُوحٍ تَقُولُ لِلنَّاسِ إِنَّهُ مَجْنُونٌ. وَكَانَتِ امْرَأَةُ لُوطٍ تُخْبِرُ بِأَضْيَافِهِ. وَعَنْهُ: مَا بَغَتِ امْرَأَةُ نَبِيٍّ قَطُّ. وَهَذَا إِجْمَاعٌ مِنَ الْمُفَسِّرِينَ فِيمَا ذَكَرَ الْقُشَيْرِيُّ.","en":"Al-Qurtubi: Sulayman ibn Ruqayya reported from Ibn Abbas that Nuh's wife used to tell people he was mad, and Lut's wife used to inform about his guests; and \"no prophet's wife ever committed adultery\", and this is a consensus of the exegetes, as al-Qushayri mentioned."}},{"id":"aisha","cat":"c","n":"عائشة وحادثة الإفك","intro":"رماها المنافقون ومن تبعهم بالإفك، فأنزل الله براءتها في آيات تُتلى، وجعل الحادثة تأديباً للمؤمنين في التثبت وحفظ الأعراض: «لا تحسبوه شراً لكم بل هو خير لكم».","eps":[{"t":"عصبة الإفك والوعيد","r":[24,11,15]},{"t":"أدب المؤمنين: لولا إذ سمعتموه","r":[24,12,18]},{"t":"براءتها: الطيبات للطيبين","r":[24,19,26]}],"ls":[{"t":"في الشر خير: براءة وتنويه وأحكام","r":[24,11,11],"q":{"bk":"saadi","w":"السعدي","s":24,"ay":11,"x":"{لا تَحۡسَبوه شرًّا لكم بل هو خيرٌ لكم}: لِما تضمَّنَ ذلك تبرئةَ أمِّ المؤمنين ونزاهتَها والتنويهَ بذِكْرها، حتى تناول عمومُ المدح سائرَ زوجاتِ النبيِّ - صلى الله عليه وسلم -، ولِما تضمَّن من بيان الآياتِ المضطرِّ إليها العباد، التي ما زال العملُ بها إلى يوم القيامة؛ فكل هذا خيرٌ عظيمٌ، لولا مقالَةُ أهل الإفك، لم يحصل بذلك ، وإذا أراد الله أمراً؛ جعل له سبباً، ولذلك جَعَلَ الخطابَ عامًّا مع المؤمنين كلهم، وأخبر أنَّ قَدْحَ بعضِهم ببعض كقدح في أنفسهم؛ ففيه أنَّ المؤمنين في توادِّهم وتراحُمِهم وتعاطُفِهم واجتماعِهم على مصالحهم كالجسدِ الواحدِ، والمؤمنُ للمؤمن كالبنيانِ يشدُّ بعضُه بعضاً؛ فكما أنَّه يكره أن يَقْدَحَ أحدٌ في عرضه؛ فليكرهْ مِنْ كلِّ أحدٍ أن يَقْدَحَ في أخيه المؤمن الذي بمنزلة نفسه، وما لم يصل العبدُ إلى هذه الحالة؛ فإنَّه من نَقْصِ إيمانه وعدم نُصحه.","en":"Al-Sa'di: \"Do not think it evil for you, rather it is good for you\", for it contained the vindication of the Mother of the Believers, her purity and the mention of her, extending praise to all the Prophet's wives, and the clear verses needed by servants, whose ruling continues until the Day of Resurrection; and the believers in their mutual love and mercy are like one body."}},{"t":"حسن الظن بالمؤمنين واجب","r":[24,12,12],"q":{"bk":"saadi","w":"السعدي","s":24,"ay":11,"x":"{12} ثم أرشدَ الله عباده عند سماع مثل هذا الكلام، فقال:{لولا إذۡ سَمِعۡتُموه ظنَّ المؤمنون والمؤمناتُ بأنفسِهم خيراً}؛ أي: ظنَّ المؤمنون بعضُهم ببعضٍ خيراً، وهو السلامة مما رُمُوا به، وأنَّ ما معهم من الإيمان المعلوم يَدْفَعُ ما قيل فيهم من الإفك الباطل.","en":"Al-Sa'di: Allah instructed His servants on hearing such words: \"why, when you heard it, did the believing men and women not think good of themselves\", meaning that believers think well of one another, safe from what they were accused of, since the faith they are known to have repels the false slander."}},{"t":"لا قذف بلا أربعة شهداء","r":[24,13,13],"q":{"bk":"saadi","w":"السعدي","s":24,"ay":11,"x":"{13}{لولا جاؤوا عليه بأربعة شهداءَ}؛ أي: هلاَّ جاء الرامون على ما رَمَوْا به بأربعة شهداء؛ أي: عدول مرضيين، {فإذۡ لم يأتوا بالشهداءِ فأولئك عندَ اللهِ هم الكاذبونَ}: وإن كانوا في أنفسِهم قد تيقَّنوا ذلك؛ فإنَّهم كاذبونَ في حكم الله؛ لأنَّه حرَّمَ عليهم التكلُّم بذلك من دون أربعة شهود، ولهذا قال:{فأولئك عند الله هم الكاذبون}: ولم يَقُلْ: فأولئك هم الكاذبون، وهذا كلُّه من تعظيم حرمةِ عِرْضِ المسلم؛ بحيثُ لا يجوز الإقدام على رميِهِ من دون نِصاب الشهادة بالصدق.","en":"Al-Sa'di: why did they not bring four witnesses, just and approved, for what they accused? \"Then if they do not bring the witnesses, those are before Allah the liars\", even if they were certain in themselves, for in Allah's ruling they are liars."}},{"t":"تلقّي الباطل بالألسن والقول بلا علم","r":[24,15,15],"q":{"bk":"saadi","w":"السعدي","s":24,"ay":11,"x":"{15}{إذ تَلَقَّوۡنَه بألسِنَتِكم}؛ أي: تلقَّفونه ويُلقيه بعضُكم إلى بعض وتستوشون حديثَه وهو قولٌ باطلٌ. {وتقولون بأفواهِكُم ما ليس لكم به علمٌ}: والأمران محظوران؛ التكلُّم بالباطل، والقولُ بلا علم.","en":"Al-Sa'di: \"when you received it with your tongues\", catching it and throwing it to one another, savouring its talk, a false saying; \"and said with your mouths what you had no knowledge of\": both are forbidden, speaking falsehood and speaking without knowledge."}}]},{"id":"ummahat","cat":"c","n":"أمهات المؤمنين","intro":"زوجات النبي ﷺ، خاطبهن الله بالتقوى وحسن القول والقرار في البيوت وإقامة الصلاة، وخيّرهن بين الدنيا وزينتها وبين الله ورسوله والدار الآخرة، فاخترن الله ورسوله كلهن، وجعلهن أمهات المؤمنين.","eps":[{"t":"التخيير","r":[33,28,29]},{"t":"الأدب والقرار والصلاة","r":[33,30,34]},{"t":"سرّ البيت والتوبة","r":[66,1,5]},{"t":"أمهات المؤمنين","r":[33,6,6]}],"ls":[{"t":"الله ورسوله والدار الآخرة هي المراد","r":[33,29,29],"q":{"bk":"saadi","w":"السعدي","s":33,"ay":28,"x":"{29}{وإن كُنتُنَّ تُرِدۡنَ الله ورسولَه والدارَ الآخرة}؛ أي: هذه الأشياء مرادُكُنَّ وغايةُ مقصودِكُنَّ، وإذا حصل لَكُنَّ الله ورسوله والجنة؛ لم تبالينَ بسعة الدنيا وضيقها ويُسرها وعُسرها، وقنعتنَّ من رسول الله بما تيسَّر، ولم تطلبنَ منه ما يشقُّ عليه، {فإنَّ الله أعدَّ للمحسناتِ منكنَّ أجراً عظيماً}: رتَّب الأجر على وصفهنَّ بالإحسان؛ لأنَّه السبب الموجب لذلك، لا لكونهنَّ زوجاتٍ للرسول؛ فإنَّ مجرَد ذلك لا يكفي، بل لا يفيدُ شيئاً مع عدم الإحسان، فخيَّرَهُنَّ رسول الله - صلى الله عليه وسلم - في ذلك، فاخترنَ الله ورسوله والدار الآخرة كلُّهن ، لم يتخلفْ منهنَّ واحدةٌ رضي الله عنهن.","en":"Al-Sa'di: if these are what you want, then whatever the world gives in breadth or narrowness you do not mind; the reward is tied to their being doers of good, not to their being the Prophet's wives, for that alone does not suffice and avails nothing without good deeds; so the Messenger gave them the choice and all of them chose Allah, His Messenger and the Hereafter; not one held back."}},{"t":"علو الهمة: فوائد التخيير","r":[33,28,29],"q":{"bk":"saadi","w":"السعدي","s":33,"ay":28,"x":"إظهار رفعتهنَّ وعلوِّ درجتهنَّ وبيان علوِّ هممهنَّ أن كان اللهُ ورسولُه والدار الآخرة مرادَهُنَّ ومقصودَهن دون الدُّنيا وحطامها.","en":"Al-Sa'di among the benefits of the choice: showing their elevation and loftiness of rank and aspiration, that Allah, His Messenger and the Hereafter were their aim and intent rather than the world and its trifles."}},{"t":"القناعة سبب اطمئنان القلب","r":[33,29,29],"q":{"bk":"saadi","w":"السعدي","s":33,"ay":28,"x":"أنَّ هذا التخيير داعٍ وموجب للقناعة التي يطمئنُّ لها القلبُ وينشرحُ لها الصدرُ، ويزول عنهنَّ جشعُ الحرص وعدم الرِّضا الموجب لقلق القلب واضطرابِهِ وهمِّه وغمِّه.","en":"Al-Sa'di among the benefits: this choice calls for and requires the contentment in which the heart is at rest and the chest expanded, and removes from them the greed of avidity and lack of satisfaction that bring restlessness, worry and distress to the heart."}}],"ctx":{"bk":"ibnkathir","w":"ابن كثير","s":33,"ay":28,"x":"قَالَ ابْنُ جَرِيرٍ: وَحَدَّثَنَا سَعِيدُ بْنُ يَحْيَى الْأُمَوِيُّ، حَدَّثَنَا أَبِي، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ، عَنْ عَمرة، عَنْ عَائِشَةَ؛ أَنَّ رَسُولَ اللَّهِ ﷺ لَمَّا نَزَلَ إِلَى نِسَائِهِ أُمِرَ أَنْ يُخَيِّرَهُنَّ، فَدَخَلَ عَليَّ فَقَالَ: \"سَأَذْكُرُ لَكِ أَمْرًا فَلَا تَعْجَلِي حَتَّى تَسْتَشِيرِي أَبَاكِ\". فَقُلْتُ: وَمَا هُوَ يَا نَبِيَّ اللَّهِ؟ قَالَ: \"إِنِّي أُمِرْتُ أَنْ أُخَيِّرَكُنَّ\"، وَتَلَا عَلَيْهَا آيَةَ التَّخْيِيرِ، إِلَى آخِرِ الْآيَتَيْنِ. قَالَتْ: فَقُلْتُ: وَمَا الَّذِي تَقُولُ لَا تَعْجَلِي حَتَّى تَسْتَشِيرِي أَبَاكِ؟ فَإِنِّي اخْتَارُ اللَّهَ وَرَسُولَهُ، فَسُرّ بِذَلِكَ، وعَرَض عَلَى نِسَائِهِ فَتَتَابَعْنَ كُلّهن، فاخترنَ اللَّهَ وَرَسُولَهُ .","en":"Ibn Kathir, via Ibn Jarir from Aisha: when the Messenger of Allah ﷺ came down to his wives he was commanded to give them the choice; he came to me and said: \"I will mention a matter to you, so do not hurry until you consult your father\"; ... then he recited the verse of the choice; she said: \"I choose Allah and His Messenger\", he was delighted, offered it to his wives and they followed one after another, all choosing Allah and His Messenger."}}],"h":[{"id":"h3432","p":"maryam","t":"خير نساء الأرض: مريم وخديجة","x":"خَيْرُ نِسَائِهَا مَرْيَمُ ابْنَةُ عِمْرَانَ، وَخَيْرُ نِسَائِهَا خَدِيجَةُ","src":[["bukhari","3432"]],"gr":"صحيح: رواه البخاري","f":"يبيّن الحديث فضل مريم ابنة عمران وخديجة بنت خويلد رضي الله عنها، وأن أفضلية النساء بالإيمان والصدّيقية لا بالنسب وحده.","en":"Ali narrated that he heard the Prophet ﷺ say: the best of her women is Maryam daughter of Imran, and the best of her women is Khadija."},{"id":"h3411","p":"asiya","t":"كمال آسية ومريم وفضل عائشة","x":"كَمَلَ مِنَ الرِّجَالِ كَثِيرٌ، وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ إِلاَّ آسِيَةُ امْرَأَةُ فِرْعَوْنَ، وَمَرْيَمُ بِنْتُ عِمْرَانَ، وَإِنَّ فَضْلَ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَامِ","src":[["bukhari","3411"]],"gr":"صحيح: رواه البخاري","f":"يشهد الحديث لمن ضربها القرآن مثلاً بالكمال، وفيه فضل عائشة على النساء كفضل الثريد على سائر الطعام.","en":"Abu Musa narrated that the Prophet ﷺ said: many men reached perfection, but of women only Asiya the wife of Pharaoh and Maryam daughter of Imran, and the merit of Aisha over women is like the merit of tharid over other food."},{"id":"h3769","p":"aisha","t":"فضل عائشة على النساء","x":"وَفَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَامِ","src":[["bukhari","3769"]],"gr":"صحيح: رواه البخاري","f":"فضل عائشة رضي الله عنها على النساء كفضل الثريد وهو أطيب الطعام عندهم، وهذه شهادة نبوية بعد براءتها في القرآن.","en":"Abu Musa narrated that the Prophet ﷺ said: and the merit of Aisha over women is like the merit of tharid over other food."}],"ay":{"41":"وَقُلۡنَا يَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","325":"۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ","326":"ذُرِّيَّةَۢ بَعۡضُهَا مِنۢ بَعۡضٖۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","327":"إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَٰنَ رَبِّ إِنِّي نَذَرۡتُ لَكَ مَا فِي بَطۡنِي مُحَرَّرٗا فَتَقَبَّلۡ مِنِّيٓۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","328":"فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّي وَضَعۡتُهَآ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّي سَمَّيۡتُهَا مَرۡيَمَ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ","329":"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ","334":"وَإِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلۡعَٰلَمِينَ","335":"يَٰمَرۡيَمُ ٱقۡنُتِي لِرَبِّكِ وَٱسۡجُدِي وَٱرۡكَعِي مَعَ ٱلرَّٰكِعِينَ","336":"ذَٰلِكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهِ إِلَيۡكَۚ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَقۡلَٰمَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُنتَ لَدَيۡهِمۡ إِذۡ يَخۡتَصِمُونَ","972":"وَيَٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ","973":"فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ","974":"وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ","975":"فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ","976":"قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ","977":"قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ","978":"قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ","1036":"فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ","1541":"وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ","1542":"فَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ","1543":"وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ","1544":"قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ","1545":"قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ","1553":"قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ","1618":"وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ","1619":"وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ","1620":"وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِيصَهُۥ مِن دُبُرٖ وَأَلۡفَيَا سَيِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَآءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوٓءًا إِلَّآ أَن يُسۡجَنَ أَوۡ عَذَابٌ أَلِيمٞ","1621":"قَالَ هِيَ رَٰوَدَتۡنِي عَن نَّفۡسِيۚ وَشَهِدَ شَاهِدٞ مِّنۡ أَهۡلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٖ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَٰذِبِينَ","1622":"وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٖ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّٰدِقِينَ","1623":"فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٖ قَالَ إِنَّهُۥ مِن كَيۡدِكُنَّۖ إِنَّ كَيۡدَكُنَّ عَظِيمٞ","1624":"يُوسُفُ أَعۡرِضۡ عَنۡ هَٰذَاۚ وَٱسۡتَغۡفِرِي لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔينَ","1625":"۞ وَقَالَ نِسۡوَةٞ فِي ٱلۡمَدِينَةِ ٱمۡرَأَتُ ٱلۡعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِي ضَلَٰلٖ مُّبِينٖ","1626":"فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَيۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـٔٗا وَءَاتَتۡ كُلَّ وَٰحِدَةٖ مِّنۡهُنَّ سِكِّينٗا وَقَالَتِ ٱخۡرُجۡ عَلَيۡهِنَّۖ فَلَمَّا رَأَيۡنَهُۥٓ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَيۡدِيَهُنَّ وَقُلۡنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنۡ هَٰذَآ إِلَّا مَلَكٞ كَرِيمٞ","1627":"قَالَتۡ فَذَٰلِكُنَّ ٱلَّذِي لُمۡتُنَّنِي فِيهِۖ وَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّٰغِرِينَ","1628":"قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ","1629":"فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَيۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","1645":"وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ","1646":"قَالَ مَا خَطۡبُكُنَّ إِذۡ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِن سُوٓءٖۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِيزِ ٱلۡـَٰٔنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ","1647":"ذَٰلِكَ لِيَعۡلَمَ أَنِّي لَمۡ أَخُنۡهُ بِٱلۡغَيۡبِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي كَيۡدَ ٱلۡخَآئِنِينَ","1648":"۞ وَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ","2265":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانٗا شَرۡقِيّٗا","2266":"فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابٗا فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرٗا سَوِيّٗا","2267":"قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا","2268":"قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمٗا زَكِيّٗا","2269":"قَالَتۡ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَلَمۡ يَمۡسَسۡنِي بَشَرٞ وَلَمۡ أَكُ بَغِيّٗا","2272":"فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا","2273":"فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيّٗا","2274":"وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا","2275":"فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدٗا فَقُولِيٓ إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمٗا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا","2276":"فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـٔٗا فَرِيّٗا","2277":"يَٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءٖ وَمَا كَانَتۡ أُمُّكِ بَغِيّٗا","2278":"فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي ٱلۡمَهۡدِ صَبِيّٗا","2279":"قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا","2280":"وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا","2384":"وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ","2385":"إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ","2386":"أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوّٞ لِّي وَعَدُوّٞ لَّهُۥۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّةٗ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ","2387":"إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسٗا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونٗاۚ فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرٖ يَٰمُوسَىٰ","2801":"إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةٞ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرّٗا لَّكُمۖ بَلۡ هُوَ خَيۡرٞ لَّكُمۡۚ لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمٞ","2802":"لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرٗا وَقَالُواْ هَٰذَآ إِفۡكٞ مُّبِينٞ","2803":"لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ","2804":"وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ","2805":"إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمٞ وَتَحۡسَبُونَهُۥ هَيِّنٗا وَهُوَ عِندَ ٱللَّهِ عَظِيمٞ","2806":"وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمٞ","2809":"إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمٞ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","2810":"وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٞ رَّحِيمٞ","2811":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدٗا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمٞ","2812":"وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٌ","2813":"إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ عَظِيمٞ","3180":"فَمَكَثَ غَيۡرَ بَعِيدٖ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإٖ يَقِينٍ","3181":"إِنِّي وَجَدتُّ ٱمۡرَأَةٗ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءٖ وَلَهَا عَرۡشٌ عَظِيمٞ","3182":"وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ فَهُمۡ لَا يَهۡتَدُونَ","3183":"أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ","3184":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩","3185":"۞ قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ","3186":"ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ","3187":"قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبٞ كَرِيمٌ","3188":"إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","3189":"أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ","3190":"قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ","3191":"قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةٖ وَأُوْلُواْ بَأۡسٖ شَدِيدٖ وَٱلۡأَمۡرُ إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ","3192":"قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةٗۚ وَكَذَٰلِكَ يَفۡعَلُونَ","3193":"وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةٖ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ","3194":"فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٖ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرٞ مِّمَّآ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ","3195":"ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم بِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةٗ وَهُمۡ صَٰغِرُونَ","3196":"قَالَ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ","3197":"قَالَ عِفۡرِيتٞ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينٞ","3198":"قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ","3200":"فَلَمَّا جَآءَتۡ قِيلَ أَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِينَ","3201":"وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمٖ كَٰفِرِينَ","3202":"قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةٗ وَكَشَفَتۡ عَن سَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحٞ مُّمَرَّدٞ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","3258":"وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ","3259":"فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ","3260":"وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ","3261":"وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","3262":"وَقَالَتۡ لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبٖ وَهُمۡ لَا يَشۡعُرُونَ","3263":"۞ وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰٓ أَهۡلِ بَيۡتٖ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ","3264":"فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","3274":"وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ","3275":"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ","3276":"فَجَآءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِي عَلَى ٱسۡتِحۡيَآءٖ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","3277":"قَالَتۡ إِحۡدَىٰهُمَا يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ","3278":"قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن تَأۡجُرَنِي ثَمَٰنِيَ حِجَجٖۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرٗا فَمِنۡ عِندِكَۖ وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰلِحِينَ","3279":"قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٞ","3538":"ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا","3560":"يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحٗا جَمِيلٗا","3561":"وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمٗا","3562":"يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةٖ مُّبَيِّنَةٖ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا","3563":"۞ وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحٗا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقٗا كَرِيمٗا","3564":"يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدٖ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضٞ وَقُلۡنَ قَوۡلٗا مَّعۡرُوفٗا","3565":"وَقَرۡنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا","3566":"وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا","4698":"هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ","4699":"إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ","4700":"فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ","4701":"فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ","4702":"فَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٖ","5104":"قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ","5105":"ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرٗا مِّنَ ٱلۡقَوۡلِ وَزُورٗاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ","5106":"وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةٖ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","5107":"فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينٗاۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ","5229":"يَٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","5230":"قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","5231":"وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ","5232":"إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ","5233":"عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَٰٓئِحَٰتٖ ثَيِّبَٰتٖ وَأَبۡكَارٗا","5238":"ضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ","5239":"وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","5240":"وَمَرۡيَمَ ٱبۡنَتَ عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ"},"nay":128,"nq":53,"nls":43};
